import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    width = 3
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    def normalize(fields):
        if len(fields) > width:
            return fields[:width - 1] + [",".join(fields[width - 1:])]
        return fields + [""] * (width - len(fields))

    header = next(reader, None)
    if header is None:
        return {"columns": [], "rows": []}

    return {
        "columns": normalize(header),
        "rows": [normalize(fields) for fields in reader],
    }
